<template><dialog ref="modal" class="selfie-modal" @cancel="cancel" @close="cleanup"><header><h2>셀피 확인</h2><button type="button" :disabled="busy" @click="close" aria-label="닫기">×</button></header><div class="selfie-body"><p>얼굴이 잘 보이게 촬영해 주세요.</p><label class="consent"><input type="checkbox" v-model="consent" :disabled="busy||!!capture"/><span>{{required?'[필수]':'[선택]'}} 셀피와 제출 당시 대표 사진을 사진 도용 확인·수동 심사 목적으로 수집·보관하는 데 동의합니다. 일반 회원에게 공개되지 않습니다. 심사 완료 후 30일, 미심사 시 제출 후 30일에 삭제됩니다. {{required?'동의하지 않으면 요청된 확인을 완료할 수 없습니다.':'동의하지 않아도 기존 기본 서비스는 이용할 수 있습니다.'}}</span></label><template v-if="capture"><strong class="challenge">{{capture.challenge}}</strong><div class="camera-frame"><video ref="video" v-show="!preview" autoplay playsinline muted/><img v-if="preview" :src="preview" alt="촬영한 셀피 미리보기"/><span v-if="!preview" class="face-guide" aria-hidden="true"/></div></template><p v-if="error" role="alert">{{error}}</p></div><footer><button v-if="!capture" class="primary" :disabled="busy||!consent" @click="start">{{busy?'카메라 여는 중…':'카메라 열기'}}</button><button v-else-if="!preview" class="primary" :disabled="busy||!ready" @click="take">촬영</button><template v-else><button :disabled="busy" @click="retake">다시 촬영</button><button class="primary" :disabled="busy||!blob||!consent" @click="submit">{{busy?'제출 중…':'이 사진 제출'}}</button></template></footer></dialog></template>
<script setup>
import {ref,nextTick,onUnmounted} from 'vue';import api from '../api/api';
defineProps({required:Boolean});const emit=defineEmits(['submitted']);
const modal=ref(),video=ref(),capture=ref(),preview=ref(''),blob=ref(),consent=ref(false),busy=ref(false),ready=ref(false),error=ref('');let stream,epoch=0;
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;ready.value=false;}
function cleanup(){epoch++;stop();if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';blob.value=null;capture.value=null;consent.value=false;}
function close(){if(busy.value)return;modal.value.close();cleanup();}
function cancel(e){if(busy.value)e.preventDefault();else cleanup();}
function open(){cleanup();error.value='';modal.value.showModal();}
async function camera(){stop();const current=epoch;const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:640}},audio:false});if(current!==epoch||!modal.value?.open){next.getTracks().forEach(t=>t.stop());return;}stream=next;await nextTick();video.value.srcObject=stream;await video.value.play();ready.value=true;}
async function start(){if(busy.value||!consent.value)return;busy.value=true;error.value='';try{capture.value=(await api.post('/selfie/start')).data;await nextTick();await camera();}catch(e){stop();capture.value=null;error.value=e.response?.data?.message||'카메라 권한을 허용해 주세요. HTTPS 주소에서 촬영할 수 있어요.';}finally{busy.value=false;}}
function take(){if(!ready.value||busy.value)return;const v=video.value;if(!v?.videoWidth)return;busy.value=true;const current=epoch,c=document.createElement('canvas'),scale=Math.min(1,800/Math.max(v.videoWidth,v.videoHeight));c.width=Math.round(v.videoWidth*scale);c.height=Math.round(v.videoHeight*scale);c.getContext('2d').drawImage(v,0,0,c.width,c.height);c.toBlob(b=>{if(current!==epoch){busy.value=false;return;}if(b){blob.value=b;preview.value=URL.createObjectURL(b);stop();}else error.value='다시 촬영해 주세요.';busy.value=false;},'image/jpeg',.9);}
async function retake(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';blob.value=null;error.value='';busy.value=true;try{await camera();}catch{error.value='카메라를 다시 열지 못했습니다.';}finally{busy.value=false;}}
async function submit(){if(busy.value||!blob.value||!consent.value)return;busy.value=true;error.value='';try{const f=new FormData();f.append('file',blob.value,'selfie.jpg');f.append('consent','true');const {data}=await api.post('/selfie/'+capture.value.id,f);emit('submitted',data);modal.value.close();cleanup();}catch(e){error.value=e.response?.data?.message||'제출하지 못했습니다.';}finally{busy.value=false;}}
onUnmounted(cleanup);defineExpose({open});
</script><style scoped>
.selfie-modal{box-sizing:border-box;width:min(480px,calc(100% - 24px));max-height:92dvh;padding:0;border:0;border-radius:22px;background:#fffaf7;color:#40332b;overflow:auto}.selfie-modal::backdrop{background:#25191199}header,footer{display:flex;align-items:center;gap:10px;padding:16px 20px;background:#fffaf7;position:sticky;z-index:2}header{top:0;justify-content:space-between}footer{bottom:0;border-top:1px solid #eee0d7}header h2{margin:0;font-size:19px}button{border:0;border-radius:12px;padding:12px 16px;background:#eee1d8;color:#604636;cursor:pointer;font:inherit}footer button{flex:1}.primary{background:#d56f4e;color:white}button:disabled{opacity:.5;cursor:default}.selfie-body{padding:0 20px 16px;font-size:13px;line-height:1.7}.muted{font-size:12px;color:#806e62}.consent{display:flex;align-items:flex-start;gap:9px;padding:12px;background:#f4ece5;border-radius:12px}.consent input{flex:none;margin-top:5px;accent-color:#d56f4e}.camera-frame{position:relative;margin-top:12px;aspect-ratio:1;max-height:38dvh;background:#eee;border-radius:16px;overflow:hidden}.camera-frame video,.camera-frame img{width:100%;height:100%;object-fit:contain;transform:scaleX(-1)}.face-guide{position:absolute;inset:10% 23%;border:2px dashed #fff9;border-radius:50%;pointer-events:none}.challenge{display:block;margin-top:16px}[role=alert]{color:#a63825}
</style>